// ## 1. Identity & Authentication Boundary
// Assets: user identity, session token, signing key (secret)
// Boundary: internet (untrusted) -> Resource API (trusted)
// INVARIANT: a request is accepted as user U only if it carries a token
//   that is (a) signature-valid, (b) unexpired, (c) not revoked in the store.
// Abuse case: attacker replays a logged-out user's token -> MUST be rejected.

import { verify } from './jwt'
import { isRevoked } from './sessions'
import { audit } from './audit'

export async function authenticate(req: Request): Promise<Principal> {
  const token = bearer(req)                       // no token => no identity
  if (!token) throw new AuthError('missing token')

  const claims = verify(token, SIGNING_KEY)       // (a) signature or throw
  if (claims.exp < now()) throw new AuthError('expired')      // (b) expiry
  if (await isRevoked(claims.sid)) throw new AuthError('revoked') // (c) revocation

  await audit('auth.accept', { sub: claims.sub, sid: claims.sid })
  return { id: claims.sub, sid: claims.sid }      // least-privilege principal
}

