import jwt from 'jsonwebtoken'
import { randomUUID } from 'crypto'

const SECRET = process.env.SESSION_SIGNING_SECRET // 32+ bytes, server-only, NEVER in repo
if (!SECRET) throw new Error('SESSION_SIGNING_SECRET not configured')

// Mint: short-lived, uniquely identified so it can be revoked.
export function issueSession(userId: string, sessionId: string) {
  const jti = randomUUID()
  const token = jwt.sign({ sub: userId, sid: sessionId, jti }, SECRET, {
    algorithm: 'HS256',
    expiresIn: '15m', // short expiry caps the replay window
  })
  return { token, jti }
}

export function sessionCookie(token: string) {
  // HttpOnly: JS cannot read it (blocks XSS theft)
  // Secure: HTTPS only (blocks network sniffing)
  // SameSite=Strict: not sent cross-site (blocks CSRF replay)
  return `session=${token}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=900`
}

// Verify on EVERY request: signature + expiry (jwt.verify) AND revocation.
export async function authenticate(token: string, revoked: RevocationStore) {
  const claims = jwt.verify(token, SECRET, { algorithms: ['HS256'] }) as any
  if (await revoked.has(claims.jti)) {
    throw new Error('token revoked') // logout / breach kill-switch
  }
  return { userId: claims.sub, sessionId: claims.sid }
}

