// threat_model_and_access_control_packet.md → §Access Control (enforced)
// Asset: Invoice (financial). Boundary: tenant isolation. Threat: BOLA (API#1).
export function authorizeInvoiceRead(subject: Subject, invoice: Invoice): Decision {
  // 1. RBAC — coarse capability. Deny-by-default: no role, no read.
  if (!subject.roles.includes('billing_reader')) {
    audit.log({ event: 'authz.deny', reason: 'rbac.no_role', sub: subject.id })
    return { allow: false, status: 403 }
  }
  // 2. ABAC — the row-level predicate RBAC cannot express.
  //    Least privilege: a reader may read only invoices in their own tenant.
  if (subject.tenantId !== invoice.tenantId) {
    audit.log({ event: 'authz.deny', reason: 'abac.cross_tenant',
                sub: subject.id, subTenant: subject.tenantId,
                objTenant: invoice.tenantId, objId: invoice.id })
    return { allow: false, status: 403 }   // <-- stops User A → tenant 88
  }
  audit.log({ event: 'authz.allow', sub: subject.id, objId: invoice.id })
  return { allow: true, status: 200 }
}

