export async function getInvoice(req: Request, res: Response) {
  const callerId = req.auth.userId            // from verified token, NEVER from body/query
  const invoiceId = req.params.id

  // Object-level authorization: scope the read to the caller's own rows.
  const invoice = await db.invoice.findFirst({
    where: { id: invoiceId, ownerId: callerId },
  })

  if (!invoice) {
    audit.log({ actor: callerId, object: `invoice:${invoiceId}`, action: 'read', result: 'deny' })
    return res.status(404).json({ error: 'Not found' })   // 404, not 403 — no existence leak
  }

  audit.log({ actor: callerId, object: `invoice:${invoiceId}`, action: 'read', result: 'allow' })
  return res.status(200).json(invoice)
}

