// PROOF: abuse case -> denied request -> audit-log evidence -> retest
// Asset: DELETE /accounts/:id  |  Boundary: gateway->accounts svc
// Control: RBAC least-privilege (support may READ, never DELETE)

const POLICY = {
  support: ['account:read'],
  admin: ['account:read', 'account:delete'],
} as const

function authorize(role: keyof typeof POLICY, action: string) {
  const allowed = POLICY[role].includes(action)
  auditLog.append({                 // observed denial: evidence, not a vibe
    ts: Date.now(),
    actor: role,
    action,
    decision: allowed ? 'ALLOW' : 'DENY',
    reason: allowed ? 'policy-grant' : 'least-privilege-violation',
  })
  if (!allowed) throw new ForbiddenError(action) // 403
}

// Abuse case: support token attempts the privileged delete
test('support token is DENIED account:delete and it is logged', () => {
  expect(() => authorize('support', 'account:delete')).toThrow(ForbiddenError)
  const line = auditLog.last()
  expect(line.decision).toBe('DENY')            // audit-log evidence
  expect(line.reason).toBe('least-privilege-violation')
})

